using System;
class Program
{
    public static void Main(string[] args)
    {
        M(1, 1, 6); // 1
        M(1, 2, 6); // 2
        M(1, 1, 3); // 3
        M(1, 2, 3); // 3
        M(1, 5, 3); // 3
        M(2, 5, 3); // 3
        M(1, 3, 4); // 4
        M(2, 1, 4); // 5
        M(2, 2, 2); // 6
    }
    public static void M(int a, int b, int c) => Console.Write(M2(a, b, c));
    public static int M2(int a, int b, int c) => (a, b, c) switch
    {
        (1,  1,  6) => 1,
        (1,  2,  6) => 2,
        (_,  _,  3) => 3,
        (1,  _,  _) => 4,
        (_,  1,  _) => 5,
        (_,  _,  _) => 6,
    };
}
